        raise ValueError("Valor pedido inválido")

    if peso_kg <= 1:
        base = 12.00
    elif peso_kg <= 5:
        base = 12.00 + 3.50 * math.ceil(peso_kg - 1)
    else:
        base = 26.00 + 2.80 * math.ceil(peso_kg - 5)

    mult = {"S": 1.00, "SE": 1.00, "CO": 1.20, "NE": 1.35, "N": 1.50}[regiao]
    freight = base * mult

    if expresso:
        freight *= 1.4

    if valor_pedido >= 299.90 and not expresso and regiao in ("S", "SE", "CO"):
        return 0.0

    if cupom is not None and cupom != "":
        cupom_code = cupom.upper()
        if cupom_code == "FRETE10":
            freight *= 0.90
        elif cupom_code == "FRETEMETADE":
            if peso_kg <= 5:
                freight *= 0.50
        else:
            raise ValueError("Cupom inválido")

    if freight < 9.90:
        freight = 9.90

    final = float(Decimal(str(freight)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return final

